24	export interface NotOrganicSessionAdapter {
25		/**
26		 * Resolve a product capability from a server-validated session. Implementors
27		 * own assertion signing/exchange, refresh, revocation, and DPoP key custody.
28		 */
29		getProductSession(
30			event: H3Event,
31			request: NotOrganicSessionRequest,
32		): Promise<NotOrganicProductSession | null>;
33	}
